import React, { useState, useEffect } from 'react';

const Alerts = ({weatherData}) => {
    // custom alert messages based on weather conditions
    if(weatherData.main.temp < 0) return '🧊 Extreme cold - bundle up.'
    if(weatherData.main.temp > 35) return '🔥 Extreme heat - stay hydrated.'
    if(weatherData.visibility < 500) return '🌁 Low visibility - avoid driving if possible.'
    if(weatherData.pop > 0.8) return '🌂 High chance of rain - consider bringing an umbrella.'
}

export default Alerts;
